# ── world scale ────────────────────────────────────────────────────────────

BELT_LEN    = 2.40                       # full line section (longer than the bench spec)
MESH_BELT_W = 0.30                       # tactile mat width (inside the rails)
BELT_TOP    = -S.MESH_THICK              # belt top run, just under the mat
ROLLER_R    = S.ROLLER_DIA / 2
BELT_BOT    = BELT_TOP - 2 * ROLLER_R    # bottom (return) run
FLOOR_Z     = -0.36                      # factory floor
HX, HY      = BELT_LEN / 2, S.BELT_WIDTH / 2


# ── helpers ────────────────────────────────────────────────────────────────

def _xform(prim, pos=None, euler=None, scale=None):
    xf = UsdGeom.Xformable(prim)
    if pos is not None:
        xf.AddTranslateOp().Set(Gf.Vec3d(*pos))
    if euler is not None:
        xf.AddRotateXYZOp().Set(Gf.Vec3f(*euler))
    if scale is not None:
        xf.AddScaleOp().Set(Gf.Vec3f(*scale))


def _bind(prim, mat):
    UsdShade.MaterialBindingAPI.Apply(prim).Bind(mat)


def _box(stage, path, dims, pos, mat, euler=None):
    c = UsdGeom.Cube.Define(stage, path)
    c.CreateSizeAttr(1.0)
    _xform(c.GetPrim(), pos, euler, tuple(dims))
    _bind(c.GetPrim(), mat)
    return c


def _cyl(stage, path, radius, height, pos, mat, axis="Z", euler=None):
    c = UsdGeom.Cylinder.Define(stage, path)
    c.CreateRadiusAttr(radius)
    c.CreateHeightAttr(height)
    c.CreateAxisAttr(axis)
    _xform(c.GetPrim(), pos, euler)
    _bind(c.GetPrim(), mat)
    return c


def _capsule(stage, path, radius, height, pos, mat, axis="Z", euler=None, scale=None):
    c = UsdGeom.Capsule.Define(stage, path)
    c.CreateRadiusAttr(radius)
    c.CreateHeightAttr(height)
    c.CreateAxisAttr(axis)
    _xform(c.GetPrim(), pos, euler, scale)
    _bind(c.GetPrim(), mat)
    return c


def _sphere(stage, path, radius, pos, mat, scale=None):
    s = UsdGeom.Sphere.Define(stage, path)
    s.CreateRadiusAttr(radius)
    _xform(s.GetPrim(), pos, None, scale)
    _bind(s.GetPrim(), mat)
    return s


def _mesh(stage, path, points, face_indices, face_counts, mat, *,
          pos=None, euler=None, scale=None, normals=None, st=None,
          smooth=True):
    """Generic USD mesh with optional smooth vertex normals + UVs."""
    m = UsdGeom.Mesh.Define(stage, path)
    m.CreatePointsAttr([Gf.Vec3f(float(p[0]), float(p[1]), float(p[2])) for p in points])
    m.CreateFaceVertexIndicesAttr([int(i) for i in face_indices])
    m.CreateFaceVertexCountsAttr([int(c) for c in face_counts])
    m.CreateSubdivisionSchemeAttr(UsdGeom.Tokens.none)
    if normals is not None:
        m.CreateNormalsAttr(
            [Gf.Vec3f(float(n[0]), float(n[1]), float(n[2])) for n in normals])
        m.SetNormalsInterpolation(UsdGeom.Tokens.vertex)
    if st is not None:
        pv = UsdGeom.PrimvarsAPI(m.GetPrim()).CreatePrimvar(
            "st", Sdf.ValueTypeNames.TexCoord2fArray,
            interpolation=UsdGeom.Tokens.vertex)
        pv.Set([Gf.Vec2f(float(uv[0]), float(uv[1])) for uv in st])
    if smooth and normals is None:
        # USD treats `none` subdiv + missing normals as flat shading; turn on
        # `catmullClark` only if the caller didn't supply geometry-correct normals.
        pass
    _xform(m.GetPrim(), pos, euler, scale)
    _bind(m.GetPrim(), mat)
    return m


# ── materials (OmniPBR/MDL with textures) ──────────────────────────────────

def _omnipbr(stage, path, *, diffuse=None, diffuse_tex=None, rough=0.5,
             rough_tex=None, normal_tex=None, metallic=0.0, metallic_tex=None,
             specular=0.5, emissive=None, emit=0.0, project_uvw=True,
             tex_scale=1.0):
    """Real OmniPBR material — metals reflect the HDRI, textures bind into the
    MDL inputs so concrete / brushed alu / Velostat actually catch the light.
    Pass either `diffuse` (Gf.Vec3) or `diffuse_tex` (filesystem path)."""
    mat = UsdShade.Material.Define(stage, path)
    sh = UsdShade.Shader.Define(stage, path + "/Shader")
    sh.SetSourceAsset("OmniPBR.mdl", "mdl")
    sh.SetSourceAssetSubIdentifier("OmniPBR", "mdl")

    def fset(name, vtype, val):
        sh.CreateInput(name, vtype).Set(val)

    def aset(name, path_):
        sh.CreateInput(name, Sdf.ValueTypeNames.Asset).Set(Sdf.AssetPath(path_))

    if diffuse_tex is not None:
        aset("diffuse_texture", diffuse_tex)
    if diffuse is not None:
        fset("diffuse_color_constant", Sdf.ValueTypeNames.Color3f, Gf.Vec3f(*diffuse))
    fset("metallic_constant", Sdf.ValueTypeNames.Float, float(metallic))
    if metallic_tex is not None:
        aset("metallic_texture", metallic_tex)
        fset("metallic_texture_influence", Sdf.ValueTypeNames.Float, 1.0)
    fset("reflection_roughness_constant", Sdf.ValueTypeNames.Float, float(rough))
    if rough_tex is not None:
        aset("reflectionroughness_texture", rough_tex)
        fset("reflection_roughness_texture_influence", Sdf.ValueTypeNames.Float, 1.0)
    if normal_tex is not None:
        aset("normalmap_texture", normal_tex)
        fset("flip_tangent_v", Sdf.ValueTypeNames.Bool, False)
    fset("specular_level", Sdf.ValueTypeNames.Float, float(specular))
    if project_uvw:
        fset("project_uvw", Sdf.ValueTypeNames.Bool, True)
        fset("texture_scale", Sdf.ValueTypeNames.Float2,
             Gf.Vec2f(tex_scale, tex_scale))
    if emissive is not None:
        fset("enable_emission", Sdf.ValueTypeNames.Bool, True)
        fset("emissive_color", Sdf.ValueTypeNames.Color3f, Gf.Vec3f(*emissive))
        fset("emissive_intensity", Sdf.ValueTypeNames.Float, float(emit))
    mat.CreateSurfaceOutput("mdl").ConnectToSource(sh.ConnectableAPI(), "out")
    return mat


